console.log('1');

setTimeout(() => console.log('2'), 0);

Promise.resolve().then(() => console.log('3'));

console.log('4');

// Output: 1, 4, 3, 2
// Sync first, then microtask (promise), then macrotask (timer)

async function main() {
  console.log('A');
  await null;
  console.log('B');
}

main();
console.log('C');

// A, C, B
// await splits the function: code after await is a microtask

const start = Date.now();
while (Date.now() - start < 3000) {
  // busy-wait — blocks everything
}
console.log('done');
// Timers and clicks queued during this wait fire only after

Promise.resolve()
  .then(() => {
    console.log('a');
    Promise.resolve().then(() => console.log('b'));
  })
  .then(() => console.log('c'));

// a, b, c — inner microtask drains before outer chain continues
